-- Study Abroad country content, BATCH 7: Saudi Arabia, Qatar, Thailand, Vietnam, Indonesia.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('saudi-arabia', 'qatar', 'thailand', 'vietnam', 'indonesia'));
UPDATE countries SET why_title = 'Why study in Saudi Arabia?', why_body = '<p>Saudi Arabia is investing heavily in higher education and research, and offers fully funded scholarships for international students through its government and universities. It is a leading centre for energy, engineering and Islamic studies.</p><ul><li>Government scholarships with free tuition for eligible international students</li><li>Leading research universities such as KAUST and KFUPM</li><li>Strong in energy, petroleum, engineering and computing</li><li>A growing number of English-taught programmes</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students are usually admitted through the national <strong>Study in Saudi</strong> platform or directly by a university, which then starts the student visa process. Sources describe the visa as linked to the admitting university.</p><ul><li>Admission letter from a Saudi university or scholarship acceptance</li><li>Passport, photographs and academic records</li><li>Medical certificate and health insurance, as required</li><li>Visa issued through the university or the Study in Saudi system (the exact procedure differs by university)</li><li>Travel is normally arranged for August or September for the autumn semester</li><li>Check whether your nationality needs extra approval for a government scholarship</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Saudi Ministry of Education and Study in Saudi site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply through the <strong>Study in Saudi</strong> portal for government scholarships, or directly to the university for self-funded study.</p><ul><li>Academic transcripts and certificates, attested</li><li>English or Arabic language proof</li><li>Personal statement and references for postgraduate courses</li><li>Passport copy and photographs</li><li>Medical report where requested</li><li>Scholarship applicants must not hold another Saudi scholarship at the same time</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>The government scholarship for international students is described as free of tuition. Self-funded study depends on the university, and private universities charge fees.</p><ul><li>Government scholarship: tuition free, with a monthly stipend, housing and a return ticket at many universities (benefits differ, so check the programme)</li><li>Self-funded tuition: varies widely by university; private universities charge more</li><li>Living costs are moderate compared with Western countries</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and the scholarship.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with strong grades</li><li><strong>Master''s and PhD:</strong> a relevant previous degree and, for research degrees, a research proposal</li><li><strong>Language:</strong> Arabic for Arabic-taught programmes; IELTS 5.5-6.5 or TOEFL for English-taught ones</li><li>Scholarships have age and nationality conditions, and some need government approval</li></ul>' WHERE slug = 'saudi-arabia';
UPDATE countries SET why_title = 'Why study in Qatar?', why_body = '<p>Qatar is home to Education City, where branch campuses of leading US and UK universities offer degrees in English, alongside Qatar University and national institutions. It is a hub for energy, engineering, media and healthcare.</p><ul><li>Branch campuses such as Texas A&M, Carnegie Mellon, Northwestern and Georgetown</li><li>Strong funding for research and facilities</li><li>Strong in engineering, energy, journalism and medicine</li><li>English-taught programmes and an international student community</li></ul>', visa_title = 'Student visa and residence permit', visa_body = '<p>Most international students are sponsored by their university, which arranges the entry visa and then a <strong>student residence permit</strong> after arrival.</p><ul><li>Admission letter from a Qatari university</li><li>Passport, photographs and academic records</li><li>Medical tests and an ID check after arrival, then the residence permit</li><li>Apply for the residence permit within the period set by the university (often within 90 days of arrival)</li><li>A student permit is tied to study and sponsorship; finishing the course does not automatically give the right to stay and work</li><li>Family members need separate authorisation</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Qatar Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Qatar University has fixed application windows for international students (for Fall 2026, undergraduate applications ran from 1 to 25 March).</p><ul><li>Academic transcripts and certificates, attested</li><li>English language proof</li><li>Personal statement and references for postgraduate courses</li><li>Entrance test or portfolio for some programmes</li><li>Passport copy and photographs</li><li>Visa requests for self-funded students are often due soon after the application window</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university. Education City institutions are among the more expensive, and scholarships are available at several universities.</p><ul><li>Tuition: for example, the University of Doha for Science and Technology estimates about QR 45,000-52,000 a year for bachelor''s programmes (2026 estimate)</li><li>Qatar University scholarship: covers tuition, a monthly allowance, housing and a yearly flight for eligible international undergraduates (reported terms)</li><li>Living costs: moderate to high</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with strong marks, and for some scholarships an average of 95% or higher</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a good grade</li><li><strong>English:</strong> IELTS 6.0-6.5 or TOEFL equivalent for most programmes</li><li>Some programmes need SAT, GRE or an interview</li></ul>' WHERE slug = 'qatar';
UPDATE countries SET why_title = 'Why study in Thailand?', why_body = '<p>Thailand offers affordable international programmes in English, a friendly culture and a central position in Southeast Asia. It is popular for hospitality, tourism, business, medicine and engineering.</p><ul><li>Lower tuition and living costs than most Western countries</li><li>English-taught Bachelor''s and Master''s programmes</li><li>Strong tourism and hospitality sector</li><li>Easy travel across Southeast Asia</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Non-Immigrant ED (Education) visa</strong>, applied for at a Thai embassy or through the Thai e-Visa system after admission.</p><ul><li>Admission letter from a Thai institution</li><li>Passport, photographs and proof of funds</li><li>Application fee: varies by embassy (for example about €70 at the Budapest embassy)</li><li>The visa is valid for an initial stay (typically 90 days) and the stay is then extended in Thailand (extension fee about ฿2,000)</li><li>ED Plus: full-time Bachelor''s or higher students can extend their stay for 1 year after graduation</li><li>Re-entry permit needed if you leave and re-enter during the initial stay</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Royal Thai Embassy or the Thai e-Visa portal site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, often through an online portal for international programmes.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Statement of purpose and references for postgraduate programmes</li><li>Portfolio or interview for some programmes</li><li>Passport copy and photographs</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs depend on the university and the programme. International programmes cost more than Thai-language programmes.</p><ul><li>Tuition: roughly THB 100,000-400,000 a year for most international programmes (estimate; medicine is more)</li><li>Living costs: about THB 15,000-30,000 a month, higher in Bangkok</li><li>Visa and extension fees: a few thousand baht</li><li>Health insurance is recommended</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or TOEFL equivalent for English-taught programmes</li><li>Some programmes may have interviews or entrance tests</li></ul>' WHERE slug = 'thailand';
UPDATE countries SET why_title = 'Why study in Vietnam?', why_body = '<p>Vietnam has fast-growing universities, low costs and an expanding economy. International students are drawn to business, engineering, IT, tourism and Vietnamese language and culture programmes.</p><ul><li>Low tuition and living costs</li><li>Programmes taught in English at several universities</li><li>A fast-growing economy with opportunities in technology and manufacturing</li><li>Scholarships from the Vietnamese government and universities</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students should hold a <strong>DH (study) visa</strong>, which most universities sponsor. You cannot change from a tourist visa to a student visa inside Vietnam.</p><ul><li>Admission letter from a Vietnamese institution</li><li>The university sponsors the visa, and approval is arranged before you travel</li><li>DH visas are short (usually up to 12 months), and renewed or converted by the school</li><li>A temporary residence card may be possible for longer stays, with support from the university</li><li>Once you complete your studies the student visa is no longer valid for residence</li><li>Check fees and validity with the university or the Vietnamese embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Vietnam Immigration Department and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Government scholarship applicants apply through the national scholarship process.</p><ul><li>Academic transcripts and certificates, legalised</li><li>English or Vietnamese language proof</li><li>Personal statement and references for postgraduate programmes</li><li>Passport copy and photographs</li><li>Health certificate</li><li>Scholarship documents where relevant</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. International programmes cost more than Vietnamese-taught programmes.</p><ul><li>Tuition: roughly US$1,000-$5,000 a year at public universities, and US$8,000-$15,000+ at international programmes such as RMIT and VinUniversity (estimates; check each university)</li><li>Living costs: about US$300-$700 a month depending on the city</li><li>Visa and permit costs vary by university</li><li>Health insurance is recommended</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required marks</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li><li><strong>Vietnamese:</strong> a language certificate or a preparatory year for Vietnamese-taught programmes</li></ul>' WHERE slug = 'vietnam';
UPDATE countries SET why_title = 'Why study in Indonesia?', why_body = '<p>Indonesia offers affordable study, scholarships through the Indonesian government and a chance to learn about one of Southeast Asia''s largest economies and cultures. Universities are strong in agriculture, marine science, engineering and Indonesian studies.</p><ul><li>KNB scholarships for students from developing countries</li><li>Programmes in English at leading universities</li><li>Strong agriculture, marine, environment and engineering programmes</li><li>Low cost of living compared with many destinations</li></ul>', visa_title = 'Student visa and permit requirements', visa_body = '<p>International students for programmes longer than about 60 days need a <strong>student visa</strong> and then a <strong>Student Stay Permit (KITAS)</strong>, usually arranged by the university''s international office.</p><ul><li>Admission letter from an Indonesian institution</li><li>Student visa issued by an Indonesian embassy or consulate, with the university as sponsor</li><li>KITAS conversion handled by the university after arrival (initial processing often takes weeks)</li><li>Passport, photographs and proof of funds or a scholarship</li><li>Students on a Student Stay Permit are not allowed to work in Indonesia</li><li>KNB scholarship holders get visa and KITAS support from the university</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Indonesian embassy and Directorate General of Immigration site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, or through the <strong>KNB</strong> scholarship process, which is run through Indonesian embassies and partner universities.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof (English or Indonesian)</li><li>Study plan or research proposal for postgraduate programmes</li><li>Letters of recommendation</li><li>Passport copy and health certificate</li><li>KNB applicants must meet age limits (about 35 for Master''s and 40 for doctoral programmes at UI)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme. Scholarships such as KNB cover tuition and give a living allowance.</p><ul><li>Tuition: varies by university and programme; public universities charge lower fees than private universities</li><li>KNB scholarship: tuition, monthly living allowance, health insurance, airfare and language training for holders</li><li>UI GREAT scholarship: tuition waiver for up to four semesters for eligible Master''s students</li><li>Living costs are low compared with Western countries</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and scholarship.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes; Indonesian (BIPA) for Indonesian-taught ones</li><li>KNB scholarships are for applicants from eligible developing countries</li></ul>' WHERE slug = 'indonesia';
COMMIT;
